import * as THREE from 'three';

const SUN_VARIATION_GLSL = /* glsl */`
uniform float uSunVariationTime;
uniform vec3 uSunVariationBasisX;
uniform vec3 uSunVariationBasisY;
uniform float uSunVariationSurfaceLevel;
uniform float uSunVariationWorldScale;
uniform float uSunVariationStrength;
uniform float uSunVariationDetailStrength;
uniform float uSunVariationSpeed;

vec3 underwaterSunGradient(vec3 cell) {
  vec3 p3 = fract(cell * vec3(0.1031, 0.1030, 0.0973));
  p3 += dot(p3, p3.yzx + 33.33);
  return -1.0 + 2.0 * fract((p3.xxy + p3.yxx) * p3.zyx);
}

float underwaterSunNoise(vec3 p) {
  vec3 cell = floor(p);
  vec3 local = fract(p);
  vec3 fade = local * local * local * (
    local * (local * 6.0 - 15.0) + 10.0
  );

  float n000 = dot(underwaterSunGradient(cell), local);
  float n100 = dot(
    underwaterSunGradient(cell + vec3(1.0, 0.0, 0.0)),
    local - vec3(1.0, 0.0, 0.0)
  );
  float n010 = dot(
    underwaterSunGradient(cell + vec3(0.0, 1.0, 0.0)),
    local - vec3(0.0, 1.0, 0.0)
  );
  float n110 = dot(
    underwaterSunGradient(cell + vec3(1.0, 1.0, 0.0)),
    local - vec3(1.0, 1.0, 0.0)
  );
  float n001 = dot(
    underwaterSunGradient(cell + vec3(0.0, 0.0, 1.0)),
    local - vec3(0.0, 0.0, 1.0)
  );
  float n101 = dot(
    underwaterSunGradient(cell + vec3(1.0, 0.0, 1.0)),
    local - vec3(1.0, 0.0, 1.0)
  );
  float n011 = dot(
    underwaterSunGradient(cell + vec3(0.0, 1.0, 1.0)),
    local - vec3(0.0, 1.0, 1.0)
  );
  float n111 = dot(
    underwaterSunGradient(cell + vec3(1.0, 1.0, 1.0)),
    local - vec3(1.0, 1.0, 1.0)
  );

  float n00 = mix(n000, n100, fade.x);
  float n10 = mix(n010, n110, fade.x);
  float n01 = mix(n001, n101, fade.x);
  float n11 = mix(n011, n111, fade.x);
  float noiseValue = mix(mix(n00, n10, fade.y), mix(n01, n11, fade.y), fade.z);
  return clamp(0.5 + noiseValue * 0.65, 0.0, 1.0);
}

float underwaterSunVariation(vec3 worldPosition) {
  vec2 lightSpace = vec2(
    dot(worldPosition, uSunVariationBasisX),
    dot(worldPosition, uSunVariationBasisY)
  ) * uSunVariationWorldScale;
  float time = uSunVariationTime * uSunVariationSpeed;

  float broad = underwaterSunNoise(
    vec3(lightSpace * vec2(1.0, 0.6), 11.0 + time * 0.025)
  );
  float broadVariation = (broad - 0.5) * 2.0;

  float depth = max(uSunVariationSurfaceLevel - worldPosition.y, 0.0);
  float broadDepthFade = mix(
    1.0,
    0.38,
    smoothstep(0.0, 180.0, depth)
  );
  float variation = broadVariation * uSunVariationStrength * broadDepthFade;

#ifndef SUN_VARIATION_DISABLE_DETAIL
  if (depth < 85.0) {
    float detail = underwaterSunNoise(
      vec3(lightSpace * vec2(2.15, 1.32), 47.0 + time * 0.06)
    );
    float detailVariation = (detail - 0.5) * 2.0;
    float detailDepthFade = 1.0 - smoothstep(15.0, 85.0, depth);
    variation += detailVariation * uSunVariationDetailStrength * detailDepthFade;
  }
#endif

  return max(1.0 + variation, 0.72);
}
`;

const DIRECT_LIGHT_CALL =
  '\t\tRE_Direct( directLight, geometryPosition, geometryNormal, geometryViewDir, geometryClearcoatNormal, material, reflectedLight );';

function createSunVariationLightsChunk() {
  const source = THREE.ShaderChunk.lights_fragment_begin;
  const directionalStart = source.indexOf('#if ( NUM_DIR_LIGHTS > 0 )');
  const directionalEnd = source.indexOf(
    '#if ( NUM_RECT_AREA_LIGHTS > 0 )',
    directionalStart,
  );
  if (directionalStart < 0 || directionalEnd < 0) {
    throw new Error('Directional light shader block was not found.');
  }

  const before = source.slice(0, directionalStart);
  const directional = source.slice(directionalStart, directionalEnd);
  const after = source.slice(directionalEnd);
  if (!directional.includes(DIRECT_LIGHT_CALL)) {
    throw new Error('Directional light contribution call was not found.');
  }
  const modulatedDirectional = directional.replace(
    DIRECT_LIGHT_CALL,
    `\t\t#if ( UNROLLED_LOOP_INDEX == 0 )
\t\t\tdirectLight.color *= underwaterSunVariation(vSunVariationWorldPosition);
\t\t#endif

${DIRECT_LIGHT_CALL}`,
  );
  return before + modulatedDirectional + after;
}

const SUN_VARIATION_LIGHTS_CHUNK = createSunVariationLightsChunk();

export function createUnderwaterSunVariation({
  surfaceLevel = 100,
  worldScale = 0.12,
  strength = 0.32,
  detailStrength = 0.07,
  speed = 1,
  detailEnabled = true,
} = {}) {
  return {
    detailEnabled,
    uniforms: {
      uSunVariationTime: { value: 0 },
      uSunVariationBasisX: { value: new THREE.Vector3(1, 0, 0) },
      uSunVariationBasisY: { value: new THREE.Vector3(0, 0, 1) },
      uSunVariationSurfaceLevel: { value: surfaceLevel },
      uSunVariationWorldScale: { value: worldScale },
      uSunVariationStrength: { value: strength },
      uSunVariationDetailStrength: { value: detailStrength },
      uSunVariationSpeed: { value: speed },
    },
  };
}

export function setUnderwaterSunDirection(variation, direction) {
  if (!variation?.uniforms || !direction) return;
  const lightDirection = direction.clone();
  if (lightDirection.lengthSq() < 1e-8) {
    lightDirection.set(0, 1, 0);
  } else {
    lightDirection.normalize();
  }
  const reference = Math.abs(lightDirection.y) < 0.98
    ? new THREE.Vector3(0, 1, 0)
    : new THREE.Vector3(1, 0, 0);
  variation.uniforms.uSunVariationBasisX.value
    .crossVectors(reference, lightDirection)
    .normalize();
  variation.uniforms.uSunVariationBasisY.value
    .crossVectors(lightDirection, variation.uniforms.uSunVariationBasisX.value)
    .normalize();
}

export function applyUnderwaterSunVariationToShader(shader, variation) {
  if (!shader || !variation?.uniforms) return;
  Object.assign(shader.uniforms, variation.uniforms);

  shader.vertexShader = shader.vertexShader
    .replace(
      '#include <common>',
      '#include <common>\nvarying vec3 vSunVariationWorldPosition;',
    )
    .replace(
      '#include <project_vertex>',
      '#include <project_vertex>\nvSunVariationWorldPosition = (modelMatrix * vec4(transformed, 1.0)).xyz;',
    );

  const lowSpecDefine = variation.detailEnabled
    ? ''
    : '#define SUN_VARIATION_DISABLE_DETAIL\n';
  shader.fragmentShader = shader.fragmentShader
    .replace(
      '#include <common>',
      `#include <common>
varying vec3 vSunVariationWorldPosition;
${lowSpecDefine}${SUN_VARIATION_GLSL}`,
    )
    .replace('#include <lights_fragment_begin>', SUN_VARIATION_LIGHTS_CHUNK);
}

export function patchUnderwaterSunVariationMaterial(material, variation) {
  if (!material || material.userData?.underwaterSunVariationPatched) return;
  const previousCompile = material.onBeforeCompile;
  const previousCacheKey = material.customProgramCacheKey?.bind(material);
  material.onBeforeCompile = (shader, renderer) => {
    previousCompile?.call(material, shader, renderer);
    applyUnderwaterSunVariationToShader(shader, variation);
  };
  material.customProgramCacheKey = () =>
    `${previousCacheKey?.() ?? ''}|underwater-sun-variation-v4-${variation.detailEnabled ? 'detail' : 'broad'}`;
  material.userData = {
    ...(material.userData || {}),
    underwaterSunVariationPatched: true,
  };
  material.needsUpdate = true;
}
